$ErrorActionPreference = "Stop"

$ProjectRoot = (Get-Location).Path
$Source = Join-Path $ProjectRoot "main.py"

if (-not (Test-Path -LiteralPath $Source -PathType Leaf)) {
    throw "main.py not found. Run this from the project folder containing main.py."
}

$Python = "python"
& $Python --version
if ($LASTEXITCODE -ne 0) {
    throw "Python was not found in this PyCharm Terminal."
}

$Stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$BackupDir = Join-Path $ProjectRoot "backup_before_modular_$Stamp"
$StageDir = Join-Path $ProjectRoot ".modular_stage_$Stamp"

New-Item -ItemType Directory -Force -Path $BackupDir | Out-Null
New-Item -ItemType Directory -Force -Path $StageDir | Out-Null

# IMPORTANT: current main.py is copied to backup before any modification.
Copy-Item -LiteralPath $Source `
    -Destination (Join-Path $BackupDir "main_before_modular.py") `
    -Force

foreach ($name in @("config.py", "modules")) {
    $p = Join-Path $ProjectRoot $name
    if (Test-Path -LiteralPath $p) {
        Copy-Item -LiteralPath $p `
            -Destination (Join-Path $BackupDir $name) `
            -Recurse -Force
    }
}

$Encoded = ""
$Bytes = [Convert]::FromBase64String($Encoded)
$PyFile = Join-Path $StageDir "modularizer.py"
[IO.File]::WriteAllBytes($PyFile, $Bytes)

$env:MODULAR_ORIGINAL_SOURCE = $Source

try {
    & $Python $PyFile $StageDir
    if ($LASTEXITCODE -ne 0) {
        throw "STAGING VALIDATION FAILED. Original main.py was NOT replaced."
    }
} finally {
    Remove-Item Env:MODULAR_ORIGINAL_SOURCE -ErrorAction SilentlyContinue
}

# Replace project files ONLY after all staging tests pass.
Copy-Item -LiteralPath (Join-Path $StageDir "main.py") `
    -Destination $Source -Force

Copy-Item -LiteralPath (Join-Path $StageDir "config.py") `
    -Destination (Join-Path $ProjectRoot "config.py") -Force

$TargetModules = Join-Path $ProjectRoot "modules"
if (Test-Path -LiteralPath $TargetModules) {
    Remove-Item -LiteralPath $TargetModules -Recurse -Force
}

Copy-Item -LiteralPath (Join-Path $StageDir "modules") `
    -Destination $TargetModules -Recurse -Force

Remove-Item -LiteralPath $StageDir -Recurse -Force

Write-Host ""
Write-Host "============================================================"
Write-Host "MODULARIZATION COMPLETE"
Write-Host "============================================================"
Write-Host "Backup: $BackupDir"
Write-Host "Created: main.py + config.py + modules\"
Write-Host "All staging checks passed before installation."
Write-Host "============================================================"
